INSERT INTO records (title, category, description, status) VALUES
('Blocked drain near Central Market', 'Drainage', 'Silt and plastic have blocked the drain along the market road. Needs 6 shovels, gloves and a truck to haul the silt. Traders have offered 10 people on Saturday.', 'Pending'),
('Rubbish pile at Bwacha bus stop', 'Waste', 'Uncollected rubbish has grown into a large heap beside the bus stop. Needs a collection truck, 20 refuse bags and rakes.', 'In progress'),
('Overgrown football ground in Chowa', 'Public space', 'Tall grass and broken bottles cover the community pitch. Needs 4 slashers, wheelbarrows and first aid supplies. Youth club members are ready to help.', 'Pending'),
('Flooded ditch behind Makululu clinic', 'Drainage', 'The ditch holds stagnant water after every rain. Needs spades, a few bags of gravel and two people who know how to re-dig the channel.', 'In progress'),
('Cleared walkway near campus gate', 'Public space', 'The walkway outside the campus gate was cleared of weeds and litter by student volunteers. Tools were borrowed from the maintenance office.', 'Completed'),
('Illegal dumping beside Kasanda road', 'Waste', 'Household waste is dumped at the roadside every week. Needs a skip bin, a warning sign and a truck to remove the existing pile.', 'Pending'),
('Choked culvert on Railway Road', 'Drainage', 'The culvert under the road is almost blocked with sand and leaves. Water flows over the road when it rains. Needs a crowbar, shovels and 8 volunteers.', 'Completed'),
('Broken bins at the community hall', 'Waste', 'Both bins outside the hall are cracked and overflow within days. Needs 4 replacement bins and a regular collection arrangement.', 'Pending'),
('Litter along the stream path', 'Public space', 'Plastic bottles and bags line the stream path used by children going to school. Needs litter pickers, gloves and 15 refuse bags.', 'In progress');
